CREATE TABLE t1a(a INT, b INT, c INT, d INT); CREATE TABLE t2a(c INT, d INT, e INT, f INT); CREATE TABLE t3a(a INT, b INT, e INT, f INT); CREATE TABLE t4a(a INT, c INT, d INT, f INT); INSERT INTO t1a VALUES(11,21,31,41),(12,22,32,42); INSERT INTO t2a VALUES(12,22,32,42),(13,23,33,43); INSERT INTO t3a VALUES(14,24,34,44),(15,25,35,45); INSERT INTO t4a VALUES(11,21,31,41),(13,23,33,43); CREATE TABLE t1b(a INT, b INT, c INT, d INT); CREATE TABLE t2b(c INT, d INT, e INT, f INT); CREATE TABLE t3b(a INT, b INT, e INT, f INT); CREATE TABLE t4b(a INT, c INT, d INT, f INT); INSERT INTO t1b VALUES(15,25,35,45),(18,28,38,48); INSERT INTO t2b VALUES(15,25,35,45),(17,27,37,47); INSERT INTO t3b VALUES(15,25,35,45),(16,26,36,46); INSERT INTO t4b VALUES(16,26,36,46),(19,29,39,49); CREATE VIEW t1 AS SELECT * FROM t1a UNION SELECT * FROM t1b; CREATE VIEW t2 AS SELECT * FROM t2a UNION SELECT * FROM t2b; CREATE VIEW t3 AS SELECT * FROM t3a UNION SELECT * FROM t3b; CREATE VIEW t4 AS SELECT * FROM t4a UNION SELECT * FROM t4b;